Review this change for security vulnerabilities.

Changed files (you may Read these and any other file in the repo):
  - Silmulator/docs/learning/drills/0010-register-width-and-encoding-constraints.html
  - Silmulator/docs/learning/lessons/0010-register-width-and-encoding-constraints.html
  - Silmulator/docs/learning/vocab/0010-register-width-and-encoding-constraints.html

Unified diff (only + lines are new):

=== DIFF: Silmulator/docs/learning/drills/0010-register-width-and-encoding-constraints.html ===
@@ -0,0 +1,665 @@
+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width,initial-scale=1">
+<title>Drill 0010 — Register Width and Encoding Constraints</title>
+<style>
+@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}}
+:root{
+  --bg:#0c1320;--surf:#18223a;--surf2:#22304e;--surf3:#2c3e62;
+  --accent:#60a5fa;--gold:#fcd34d;--green:#34d399;--red:#f87171;--orange:#fb923c;
+  --text:#dde5f5;--dim:#5a6a8a;--border:#243052;--code:#080e1c;
+  --mono:'Cascadia Code','Fira Mono','Consolas',monospace;
+}
+*{box-sizing:border-box;margin:0;padding:0}
+body{font-family:'Segoe UI',system-ui,sans-serif;background:var(--bg);color:var(--text);
+     font-size:15px;line-height:1.68;min-height:100vh}
+.screen{display:none;max-width:800px;margin:0 auto;padding:2rem 1.5rem 4rem}
+.screen.active{display:block}
+
+/* ── start ──────────────────────────────────────────────────── */
+.hd{text-align:center;margin-bottom:2.2rem}
+.lbl{font-family:var(--mono);font-size:.72rem;color:var(--dim);letter-spacing:.15em;
+     text-transform:uppercase;margin-bottom:.4rem}
+.ttl{font-size:2rem;color:#fff;margin-bottom:.4rem}
+.sub{color:var(--accent);font-size:.95rem}
+
+.chips{display:flex;flex-wrap:wrap;gap:.55rem;justify-content:center;margin:1.4rem 0}
+.chip{font-family:var(--mono);font-size:.8rem;padding:.35rem .85rem;
+      border:1px solid var(--border);border-radius:20px;cursor:pointer;
+      background:var(--surf);color:var(--dim);user-select:none;transition:all .15s}
+.chip.on{border-color:var(--accent);color:var(--accent);background:rgba(96,165,250,.1)}
+.chip.all{border-color:var(--gold);color:var(--gold);background:rgba(252,211,77,.07)}
+.chip.all.on{border-color:var(--gold);color:var(--gold)}
+
+.smeta{text-align:center;color:var(--dim);font-size:.85rem;margin-bottom:.9rem}
+.shuf{display:flex;align-items:center;justify-content:center;gap:.65rem;
+      margin-bottom:1.4rem;font-size:.86rem;color:var(--dim)}
+.tog{position:relative;display:inline-block;width:36px;height:20px}
+.tog input{opacity:0;width:0;height:0}
+.sl{position:absolute;inset:0;background:var(--surf2);border-radius:20px;cursor:pointer;transition:background .2s}
+.sl:before{content:'';position:absolute;width:14px;height:14px;left:3px;top:3px;
+           background:#fff;border-radius:50%;transition:transform .2s}
+input:checked+.sl{background:var(--accent)}
+input:checked+.sl:before{transform:translateX(16px)}
+
+/* ── question ───────────────────────────────────────────────── */
+.qhdr{display:flex;align-items:center;gap:.8rem;margin-bottom:1.5rem;flex-wrap:wrap}
+.qnum{font-family:var(--mono);font-size:.78rem;color:var(--dim)}
+.pbar{flex:1;height:5px;background:var(--surf2);border-radius:3px;min-width:80px}
+.pfill{height:100%;background:var(--accent);border-radius:3px;transition:width .3s}
+.ctag{font-family:var(--mono);font-size:.7rem;padding:.18rem .55rem;
+      border:1px solid var(--border);border-radius:12px;color:var(--dim)}
+.ttag{font-family:var(--mono);font-size:.7rem;padding:.18rem .55rem;border-radius:12px}
+.ttag.mc{background:rgba(96,165,250,.12);color:var(--accent)}
+.ttag.wr{background:rgba(251,146,60,.12);color:var(--orange)}
+
+.qtxt{font-size:1.05rem;font-weight:600;color:#fff;margin-bottom:1.1rem;line-height:1.5}
+pre.snip{background:var(--code);border:1px solid var(--border);border-radius:6px;
+         padding:.9rem 1.1rem;overflow-x:auto;font-family:var(--mono);font-size:.82rem;
+         line-height:1.6;margin-bottom:1.1rem;display:none}
+.kw{color:#c792ea}.str{color:#c3e88d}.cm{color:#405060;font-style:italic}
+.fn{color:#82aaff}.num{color:#f78c6c}.cls{color:#ffcb6b}.at{color:#a5d6ff}
+.del{color:#f87171}.add{color:#34d399}
+
+/* mc */
+.opts{list-style:none;margin:0;padding:0}
+.opts li{background:var(--surf);border:1px solid var(--border);border-radius:6px;
+         padding:.55rem 1rem;margin-bottom:.45rem;cursor:pointer;user-select:none;
+         transition:border-color .15s,background .15s}
+.opts li:hover:not(.lk){border-color:var(--accent);background:rgba(96,165,250,.07)}
+.opts li:focus{outline:2px solid var(--accent);outline-offset:2px}
+.opts li.ok{border-color:var(--green);background:rgba(52,211,153,.09);color:var(--green)}
+.opts li.no{border-color:var(--red);background:rgba(248,113,113,.09);color:var(--red)}
+.opts li.lk{cursor:default}
+.mfb{margin-top:.65rem;font-size:.87rem;padding:.45rem .8rem;border-radius:4px;display:none}
+.mfb.ok{background:rgba(52,211,153,.1);color:var(--green);border:1px solid rgba(52,211,153,.28)}
+.mfb.no{background:rgba(248,113,113,.09);color:var(--red);border:1px solid rgba(248,113,113,.28)}
+
+/* written */
+textarea{width:100%;min-height:108px;background:var(--surf);border:1px solid var(--border);
+         border-radius:6px;padding:.7rem .9rem;color:var(--text);font-family:inherit;
+         font-size:.92rem;resize:vertical;line-height:1.55}
+textarea:focus{outline:2px solid var(--accent)}
+.wacts{display:flex;gap:.55rem;margin-top:.65rem;flex-wrap:wrap}
+.kwres{margin-top:.8rem;display:none}
+.tally{font-weight:700;margin-bottom:.4rem;font-size:.9rem}
+.kwchips{display:flex;flex-wrap:wrap;gap:.35rem;margin-bottom:.55rem}
+.kc{font-family:var(--mono);font-size:.75rem;padding:.18rem .5rem;border-radius:12px}
+.kc.h{background:rgba(52,211,153,.12);color:var(--green);border:1px solid rgba(52,211,153,.28)}
+.kc.m{background:rgba(248,113,113,.1);color:var(--red);border:1px solid rgba(248,113,113,.28)}
+.knote{color:var(--dim);font-size:.78rem}
+.modans{display:none;margin-top:.8rem;background:var(--surf);border:1px solid var(--border);
+        border-radius:6px;padding:.8rem 1rem;font-size:.9rem;line-height:1.65;white-space:pre-wrap}
+.modlbl{font-family:var(--mono);font-size:.7rem;color:var(--dim);text-transform:uppercase;
+        letter-spacing:.08em;margin-bottom:.35rem}
+.sr{display:none;align-items:center;gap:.5rem;flex-wrap:wrap;
+    font-size:.85rem;color:var(--dim);margin-top:.65rem}
+
+/* nav + buttons */
+.nav{display:flex;gap:.55rem;margin-top:1.5rem;flex-wrap:wrap;align-items:center}
+.spc{flex:1}
+.btn{font-family:var(--mono);font-size:.83rem;padding:.45rem 1rem;border:1px solid transparent;
+     border-radius:5px;cursor:pointer;transition:opacity .15s;user-select:none}
+.btn:focus{outline:2px solid var(--accent);outline-offset:2px}
+.pri{background:var(--accent);color:#000}.pri:hover{opacity:.82}
+.sec{background:var(--surf2);color:var(--text);border-color:var(--border)}
+.sec:hover{border-color:var(--accent)}
+.grn{background:var(--green);color:#000}
+.gld{background:var(--gold);color:#000}
+.sm{padding:.32rem .7rem;font-size:.77rem}
+.red{background:var(--red);color:#fff}
+
+/* results */
+.rhdr{text-align:center;margin-bottom:1.8rem}
+.sbig{font-size:3.4rem;font-family:var(--mono);color:var(--accent)}
+.slbl{color:var(--dim);font-size:.88rem;margin-top:.25rem}
+.rcols{display:grid;grid-template-columns:1fr 1fr;gap:1rem;margin:1.4rem 0}
+@media(max-width:520px){.rcols{grid-template-columns:1fr}}
+.rcard{background:var(--surf);border:1px solid var(--border);border-radius:7px;padding:.9rem 1.1rem}
+.rcard h3{font-family:var(--mono);font-size:.78rem;color:var(--dim);
+          text-transform:uppercase;letter-spacing:.08em;margin-bottom:.6rem}
+.miss{background:var(--surf2);border-radius:4px;padding:.38rem .65rem;
+      margin-bottom:.38rem;font-size:.86rem}
+.mcorr{color:var(--green);font-family:var(--mono);font-size:.8rem;display:block;margin-top:.2rem}
+</style>
+</head>
+<body>
+<!-- ═══════════ START ═══════════ -->
+<div id="S" class="screen active">
+<div class="hd">
+  <div class="lbl">Drill 0010 · Active Recall</div>
+  <div class="ttl">Register Width and Encoding Constraints</div>
+  <div class="sub">24 questions — 16-bit width math, ID×TAIDEX reachability, reject-vs-mask policy, commit a20fbb1 code, spot-the-bug SIL scenarios</div>
+</div>
+<p style="text-align:center;color:var(--dim);font-size:.87rem;margin-bottom:1rem">Pick channels to drill, or keep All.</p>
+<div class="chips" id="chips">
+  <div class="chip all on" data-ch="all">⚡ All</div>
+  <div class="chip on" data-ch="width">Width math</div>
+  <div class="chip on" data-ch="enc">Encoding reachability</div>
+  <div class="chip on" data-ch="reject">Reject vs mask</div>
+  <div class="chip on" data-ch="code">Real code (a20fbb1)</div>
+  <div class="chip on" data-ch="bug">Spot the bug</div>
+</div>
+<p class="smeta" id="smeta">24 questions selected</p>
+<div class="shuf">
+  Shuffle
+  <label class="tog"><input type="checkbox" id="sh" checked><span class="sl"></span></label>
+</div>
+<div style="text-align:center">
+  <button class="btn pri" onclick="go()" style="font-size:1rem;padding:.65rem 2rem">Begin →</button>
+</div>
+</div>
+
+<!-- ═══════════ QUESTION ═══════════ -->
+<div id="Q" class="screen">
+<div class="qhdr">
+  <span class="qnum" id="qn">Q 1 / 24</span>
+  <div class="pbar"><div class="pfill" id="pf" style="width:0%"></div></div>
+  <span class="ctag" id="ct"></span>
+  <span class="ttag mc" id="tt">MC</span>
+</div>
+<div class="qtxt" id="qt"></div>
+<pre class="snip" id="qs"></pre>
+
+<div id="MA" style="display:none">
+  <ul class="opts" id="mo"></ul>
+  <div class="mfb" id="mf"></div>
+</div>
+
+<div id="WA" style="display:none">
+  <textarea id="wa" placeholder="Type your answer here…"></textarea>
+  <div class="wacts">
+    <button class="btn sec sm" onclick="chkW()">Check keywords</button>
+    <button class="btn sec sm" onclick="showM()">Show model answer</button>
+  </div>
+  <div class="kwres" id="kr">
+    <div class="tally" id="kt"></div>
+    <div class="kwchips" id="kc"></div>
+    <div class="knote">⚠ Keyword check is fuzzy — judge honestly against the model answer.</div>
+  </div>
+  <div class="modans" id="md"><div class="modlbl">Model answer</div><div id="mt"></div></div>
+  <div class="sr" id="sr">
+    Rate yourself:
+    <button class="btn grn sm" onclick="rate('k')">✓ Knew it</button>
+    <button class="btn red sm"  onclick="rate('r')">↺ Needs review</button>
+  </div>
+</div>
+
+<div class="nav">
+  <button class="btn sec sm" id="bp" onclick="prev()">← Prev</button>
+  <div class="spc"></div>
+  <button class="btn pri sm" id="bn" onclick="next()">Next →</button>
+  <button class="btn gld sm" id="bf" style="display:none" onclick="results()">Results</button>
+</div>
+</div>
+
+<!-- ═══════════ RESULTS ═══════════ -->
+<div id="R" class="screen">
+<div class="rhdr">
+  <div class="sbig" id="rb">—</div>
+  <div class="slbl" id="rl"></div>
+</div>
+<div class="rcols">
+  <div class="rcard"><h3>MC misses</h3><div id="rm"><em style="color:var(--dim);font-size:.86rem">None!</em></div></div>
+  <div class="rcard"><h3>Written — needs review</h3><div id="rw"><em style="color:var(--dim);font-size:.86rem">None flagged.</em></div></div>
+</div>
+<div style="display:flex;gap:.6rem;justify-content:center;flex-wrap:wrap;margin-top:.8rem">
+  <button class="btn sec" onclick="rev()">Review missed only</button>
+  <button class="btn pri" onclick="location.reload()">Restart</button>
+</div>
+</div>
+
+<script>
+// ══════════════════════════════════════════════════════════════
+// QUESTION BANK  (24 questions — grounded in commit a20fbb1)
+// ══════════════════════════════════════════════════════════════
+const BANK = [
+// ─── CHANNEL: width ───────────────────────────────────────────
+{id:'w1',ch:'width',type:'w',
+ q:'TAxR is described as "a 16-bit counter". Derive its representable value range, explain why 0xFFFF is accepted but 0x10000 is not, and state what the model does for each write after commit a20fbb1.',
+ c:[{l:'16 bits → 0 … 2^16 − 1 = 65535 (0xFFFF)',t:['65535','0xffff','2^16','2**16','16 bits']},
+    {l:'0x10000 needs a 17th bit — unrepresentable',t:['0x10000','17','65536','does not fit','cannot hold','unrepresentable']},
+    {l:'0xFFFF stored and reads back; 0x10000 → ScpiError -222',t:['-222','rejected','out of range','stored']},
+    {l:'state unchanged on rejection',t:['unchanged','previous','not stored','untouched','before the assignment']}],
+ m:`Sixteen flip-flops represent exactly 2^16 = 65536 states: the integers 0 through 65535 (0xFFFF). 0xFFFF is the all-ones pattern — the last representable value — so TIMERA0:COUNT 0xFFFF stores and reads back 65535 (test_count_16bit_maximum pins this, with zero errors).
+0x10000 is 65536: it needs a seventeenth bit that the register does not have. It is not "too big and wraps" — in the register it simply has no representation.
+After a20fbb1, _timer_count guards the write: if not 0 <= v <= 0xFFFF, it raises ScpiError(-222, "Timer count out of range (0-0xFFFF)") BEFORE assignment, so ts.count keeps its previous value. Before the fix, the model stored 0x12345-style values verbatim — an unreachable state that voided any SIL result computed from it.`
+},
+
+{id:'w2',ch:'width',type:'mc',
+ q:'What does TIMERA0:COUNT -1 do after commit a20fbb1?',
+ snip:`v = int(cmd.params[<span class="num">0</span>], <span class="num">0</span>)
+<span class="kw">if not</span> <span class="num">0</span> &lt;= v &lt;= <span class="num">0xFFFF</span>:
+    <span class="kw">raise</span> <span class="cls">ScpiError</span>(-<span class="num">222</span>, <span class="str">"Timer count out of range (0-0xFFFF)"</span>)`,
+ opts:[
+  {t:'Queues -222 — the guard is two-sided, and an unsigned 16-bit register cannot represent a negative value',c:true, w:'Correct. The chained comparison 0 <= v <= 0xFFFF rejects both directions of unrepresentability: too big (0x10000) and negative (-1). TAxR holds bit patterns 0…65535; there is no sign bit.'},
+  {t:'Stores 0xFFFF — negative values wrap two\'s-complement style',c:false,w:'Two\'s-complement wrapping is a CPU-arithmetic convention, not a register-write policy. The model rejects rather than reinterpreting the bits.'},
+  {t:'Stores -1 — Python ints are signed',c:false,w:'Python would happily hold -1, which is exactly why the explicit guard exists: the modeling language is wider than the modeled register in both directions.'},
+  {t:'Queues -224 — negative numbers are not in the valid set',c:false,w:'-224 is for finite-set membership violations (DIVIDER 128). A numeric magnitude/sign outside the representable range is -222, Data out of range.'},
+ ]
+},
+
+{id:'w3',ch:'width',type:'mc',
+ q:'Which of these writes succeeds with no error after a20fbb1?',
+ opts:[
+  {t:'TIMERA0:CC0:VALUE 0xFFFF',c:true, w:'Correct. 0xFFFF = 65535 is the top of the representable range — a boundary value, not an overflow. test_capture_compare_boundary_value pins that it stores and reads back exactly.'},
+  {t:'TIMERA0:CC1:VALUE 70000',c:false,w:'70000 > 65535 → ScpiError(-222, "CCR value out of range (0-0xFFFF)"). CCRn got the same width guard as COUNT.'},
+  {t:'TIMERA0:COUNT 0x12345',c:false,w:'0x12345 = 74565 needs 17 bits. This is the exact value the audit probe used to demonstrate the old verbatim-store defect; it is now rejected with -222.'},
+  {t:'TIMERA0:CLOCK:DIVIDER 128',c:false,w:'128 fits in 16 bits but no ID×TAIDEX encoding produces it — rejected with -224. Width is fine; reachability is not.'},
+ ]
+},
+
+{id:'w4',ch:'width',type:'w',
+ q:'A masking policy would compute count = value & 0xFFFF. Apply it to 0x12345 and to 0x10000, then explain why the flipped test test_count_over_16bit_rejected_or_masked accepts masking even though this repo rejects instead.',
+ c:[{l:'0x12345 & 0xFFFF = 0x2345 (9029)',t:['0x2345','9029']},
+    {l:'0x10000 & 0xFFFF = 0',t:['0x0000',' 0','= 0','zero']},
+    {l:'mask keeps only the low 16 bits — what a 16-bit bus write would land',t:['low 16','lower 16','truncat','bus','& 0xffff']},
+    {l:'both policies keep state representable; test asserts errors==1 OR count<=0xFFFF',t:['either','or count','representable','both','defensible','<= 0xffff']}],
+ m:`Masking keeps only the low 16 bits:
+- 0x12345 & 0xFFFF = 0x2345 (9029) — the leading 1 is discarded.
+- 0x10000 & 0xFFFF = 0x0000 — all the value was in the 17th bit.
+That is what real silicon effectively does for a bus write: only 16 wires arrive, so only 16 bits land. The test asserts "errors(mcu) == 1 or mcu.timer_a[0].count <= 0xFFFF" because BOTH policies keep the state space honest — either the write is refused (reject) or the stored value is representable (mask). What the test forbids is the third option: storing the over-width value verbatim.
+This repo chose reject (-222) over mask because the un-truncated value arriving at the SCPI layer is evidence of a firmware/test bug, and a queued error diagnoses it at the offending line, whereas masking would silently reproduce the confusing hardware outcome.`
+},
+
+{id:'w5',ch:'width',type:'mc',
+ q:'At a 1-MHz timer tick, firmware wants a 200-ms period and computes 200000 counts. What happens on TIMERA0:PERIOD 200000, and what is the correct engineering fix?',
+ opts:[
+  {t:'-222 queued (PERIOD inherits CCR0\'s 16-bit guard); fix by raising the clock divider so the count fits, e.g. /4 → 50000 counts',c:true, w:'Correct. PERIOD delegates to _timer_cc_val(cmd, ts, 0), so the CCR width guard applies: 200000 > 65535 → -222. The design fix is to trade resolution for range via the prescaler: at /4 the tick is 250 kHz and 200 ms = 50000 counts ≤ 0xFFFF.'},
+  {t:'The period is stored; PERIOD is a logical setting, not a register',c:false,w:'Since a20fbb1, PERIOD IS the TAxCCR0 register (one store, two names) — so it is exactly as wide as CCR0: 16 bits.'},
+  {t:'-224 queued — 200000 is not in the period\'s valid set',c:false,w:'The period is a numeric range (0…0xFFFF), not an enumerated set, so the range-violation code -222 applies.'},
+  {t:'The value is split across CCR0 and CCR1 automatically',c:false,w:'No such widening exists in the timer. Long intervals need a bigger divider or software rollover counting.'},
+ ]
+},
+// ─── CHANNEL: enc ─────────────────────────────────────────────
+{id:'e1',ch:'enc',type:'w',
+ q:'Enumerate the reachable timer clock dividers from the ID and TAIDEX fields (SLAU367P §25.2.1.1): give the two field ranges, the size of the reachable set, the maximum, and two examples of values below 64 that are NOT reachable.',
+ c:[{l:'ID ∈ {1,2,4,8} (2 bits); TAIDEX ∈ {1…8} (3 bits)',t:['1,2,4,8','{1, 2, 4, 8}','1-8','1…8','1 to 8','taidex']},
+    {l:'divider = ID × TAIDEX product',t:['product','×','multipl','x taidex']},
+    {l:'20 distinct reachable values; max 8×8 = 64',t:['20','64','8×8','8 x 8','8*8']},
+    {l:'unreachable below 64: e.g. 9, 11, 13, 15, 17…',t:['9','11','13','15','17']}],
+ m:`ID is a 2-bit field in TAxCTL dividing by 1, 2, 4, or 8. TAIDEX is a 3-bit field in TAxEX0 dividing by 1 through 8. The effective divider is the product ID × TAIDEX.
+Enumerating all 4 × 8 = 32 combinations and collapsing duplicates gives 20 distinct values: {1,2,3,4,5,6,7,8,10,12,14,16,20,24,28,32,40,48,56,64}. The maximum is 8 × 8 = 64.
+Not every integer below 64 is reachable: 9, 11, 13, 15, 17 (and any value with a prime factor other than 2, 3, 5, 7 arranged outside {1,2,4,8}×{1..8}) has no factorisation into the two fields. And /128 would need a 16 in one field — no 2-bit or 3-bit encoding provides one, which is why the old model's acceptance of 128 was a compliance bug.`
+},
+
+{id:'e2',ch:'enc',type:'mc',
+ q:'What does the fixed model do with TIMERA0:CLOCK:DIVIDER 128, per the rewritten audit probe?',
+ snip:`<span class="cm"># scripts/audit_msp430.py — AFTER a20fbb1</span>
+<span class="kw">def</span> <span class="fn">probe_timer_divider_128</span>(dev):
+    <span class="str">"""/128 is rejected — no ID×TAIDEX combination produces it (§25.2.1.1)."""</span>
+    dev.process(<span class="str">"TIMERA0:CLOCK:DIVIDER 128"</span>)
+    <span class="kw">return</span> _errors(dev) == <span class="num">1</span> <span class="kw">and</span> dev.timer_a[<span class="num">0</span>].clock_divider == <span class="num">1</span>`,
+ opts:[
+  {t:'One error is queued (-224 "Illegal divider: 128") and the divider stays at its previous value — the reset default 1 in the probe',c:true, w:'Correct. 128 fails the VALID = {1,2,4,8,16,32,64} membership test, ScpiError(-224) is raised before assignment, and clock_divider keeps its prior value. The probe checks == 1 because on a fresh device the divider is still the reset default.'},
+  {t:'The divider is clamped to the nearest reachable value, 64',c:false,w:'No coercion happens anywhere in this model — validation is strict membership, and rejected writes leave state untouched.'},
+  {t:'128 is stored — it is a power of two like the rest of the set',c:false,w:'That was the pre-fix defect. Being a power of two is irrelevant; what matters is that no ID×TAIDEX product reaches 128.'},
+  {t:'-222 is queued because 128 exceeds the range maximum of 64',c:false,w:'The handler raises -224, not -222: the divider is an enumerated value set (membership check), not a continuous numeric range. Note the audit prose loosely says "rejected"; the code is the authority.'},
+ ]
+},
+
+{id:'e3',ch:'enc',type:'mc',
+ q:'Hardware CAN divide by 48 (ID=8 × TAIDEX=6), yet TIMERA0:CLOCK:DIVIDER 48 is rejected. Is that a compliance bug?',
+ opts:[
+  {t:'No — the model exposes the power-of-two subset {1,2,4,8,16,32,64} of the reachable products; refusing a reachable value is a documented simplification, unlike accepting an unreachable one',c:true, w:'Correct. The two error directions are asymmetric. Accepting /128 (unreachable) lets SIL tests validate impossible hardware — a compliance bug. Rejecting /48 (reachable but unexposed) merely narrows the model; a test hits a loud -224 and the limitation is discoverable. Every accepted value is achievable in silicon, which is the invariant that matters.'},
+  {t:'Yes — the model must accept every value the hardware can produce',c:false,w:'Completeness is desirable but its absence fails loudly (-224 at the call site). The audit reserves ACCEPTS_INVALID/NON_COMPLIANT for the silent direction: accepting what hardware cannot do.'},
+  {t:'Yes — 48 is rejected with the wrong error code',c:false,w:'-224 is the right code for a value outside the accepted set; the question is whether the set should include 48, and that is a scope choice, not a code-selection issue.'},
+  {t:'No — /48 is not actually reachable, because TAIDEX only takes powers of two',c:false,w:'TAIDEX is a 3-bit field covering 1 through 8 including 6 — /48 = 8×6 is genuinely reachable. The model still doesn\'t expose it, by design.'},
+ ]
+},
+
+{id:'e4',ch:'enc',type:'mc',
+ q:'Which pair correctly matches each rejected write to its SCPI error code?',
+ opts:[
+  {t:'COUNT 0x10000 → -222 (out of range); CC1:MODE BANANA → -224 (illegal value)',c:true, w:'Correct. -222 "Data out of range" is for numeric magnitudes outside the representable range (width guards on COUNT/CCR). -224 "Illegal parameter value" is for set-membership failures (CC mode tokens, the divider set, timer MODE).'},
+  {t:'COUNT 0x10000 → -224; CC1:MODE BANANA → -222',c:false,w:'Reversed. Range violations take -222; membership violations take -224.'},
+  {t:'Both are -222 — every bad parameter is out of range',c:false,w:'BANANA is not "out of range" — it is not in the CC mode value set {COMPARE, CAPTURE} at all. That classification difference is exactly what the two codes encode.'},
+  {t:'Both are -224 — every bad parameter is an illegal value',c:false,w:'The width guards deliberately use -222: the parameter type and set are fine, the magnitude is not representable in 16 bits.'},
